module multiplier_core_41
(
  input CLK,
  input update,
  input [16-1:0] a,
  input [11-1:0] b,
  output [27-1:0] c
);

  reg signed [16-1:0] _a;
  reg [11-1:0] _b;
  wire signed [27-1:0] _mul;
  reg signed [27-1:0] _pipe_mul0;
  assign _mul = _a * $signed({ 1'd0, _b });
  assign c = _pipe_mul0;

  always @(posedge CLK) begin
    if(update) begin
      _a <= a;
      _b <= b;
      _pipe_mul0 <= _mul;
    end 
  end


endmodule

